import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';

const spacesClient = new S3Client({
  region: process.env.DO_SPACES_REGION!,
  endpoint: `https://${process.env.DO_SPACES_REGION}.digitaloceanspaces.com`,
  credentials: {
    accessKeyId: process.env.DO_SPACES_KEY!,
    secretAccessKey: process.env.DO_SPACES_SECRET!,
  },
});

async function uploadToSpaces(
  key: string,
  body: Buffer | string,
  contentType: string,
  isPublic = false
): Promise<string> {
  const command = new PutObjectCommand({
    Bucket: process.env.DO_SPACES_BUCKET!,
    Key: key,
    Body: body,
    ContentType: contentType,
    ACL: isPublic ? 'public-read' : 'private',
  });

  await spacesClient.send(command);

  // Public URL format for Spaces
  const region = process.env.DO_SPACES_REGION!;
  const bucket = process.env.DO_SPACES_BUCKET!;
  return `https://${bucket}.${region}.digitaloceanspaces.com/${key}`;
}

// Usage: upload a publicly readable image
const publicUrl = await uploadToSpaces(
  'images/product-hero.jpg',
  imageBuffer,
  'image/jpeg',
  true
);
console.log('Uploaded to Spaces:', publicUrl);

import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';

const spacesClient = new S3Client({
  region: process.env.DO_SPACES_REGION!,
  endpoint: `https://${process.env.DO_SPACES_REGION}.digitaloceanspaces.com`,
  credentials: {
    accessKeyId: process.env.DO_SPACES_KEY!,
    secretAccessKey: process.env.DO_SPACES_SECRET!,
  },
});

// CDN must be enabled on the Space via the DigitalOcean dashboard first.
// Once enabled, the CDN endpoint follows this pattern:
function getCdnUrl(key: string): string {
  const bucket = process.env.DO_SPACES_BUCKET!;
  const region = process.env.DO_SPACES_REGION!;
  // Default CDN endpoint: {bucket}.{region}.cdn.digitaloceanspaces.com
  return `https://${bucket}.${region}.cdn.digitaloceanspaces.com/${key}`;
}

async function uploadAndGetCdnUrl(
  key: string,
  body: Buffer,
  contentType: string
): Promise<{ originUrl: string; cdnUrl: string }> {
  const command = new PutObjectCommand({
    Bucket: process.env.DO_SPACES_BUCKET!,
    Key: key,
    Body: body,
    ContentType: contentType,
    ACL: 'public-read',
    // Set cache headers for CDN
    CacheControl: 'public, max-age=31536000',
  });

  await spacesClient.send(command);

  const bucket = process.env.DO_SPACES_BUCKET!;
  const region = process.env.DO_SPACES_REGION!;

  return {
    originUrl: `https://${bucket}.${region}.digitaloceanspaces.com/${key}`,
    cdnUrl: getCdnUrl(key),
  };
}

// Usage
const { originUrl, cdnUrl } = await uploadAndGetCdnUrl(
  'assets/logo.png',
  logoBuffer,
  'image/png'
);
console.log('Origin URL:', originUrl);
console.log('CDN URL:', cdnUrl);
